        engineeringData: { blockDesign: "Open-deck Aluminum block with cast-iron cylinder liners. The N55 replaced the twin-turbo N54, focusing on improved reliability and efficiency by switching to a single twin-scroll turbocharger and integrating Valvetronic. It is the ideal engine size for the massive 7-Series-based F07 chassis.", crankshaft: "Forged Steel, supported by 7 main bearings. Exceptionally smooth naturally due to the inline-6 layout.", pistonSpeed: "14.4 m/s @ 6000 RPM.", alternator: "170A or 210A Valeo/Bosch (Multi-rib belt driven).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy.", wristPinDiameter: "22 mm.", connectingRodLength: "144.3 mm.", rodBoltSize: "M9.", crankMainJournal: "50.0 mm.", crankRodJournal: "50.0 mm.", rodRatio: "1.60." }, cylinderHead: { combustionChamberVol: "Pent-roof combustion chamber.", intakePortFlow: "24-valve DOHC design. Intake tracts require walnut blasting.", valveSizes: "Intake: 32.0 mm / Exhaust: 29.0 mm.", valveStemDiameter: "5.0 mm.", camshaftDuration: "Variable on BOTH Intake and Exhaust sides. Controlled by Double VANOS and Valvetronic.", lifterType: "Hydraulic bucket tappets.", specialFeature: "TwinPower Turbo & Valvetronic. A single twin-scroll turbocharger paired with Valvetronic entirely replaces the traditional throttle butterfly for immediate response." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Variable displacement rotor pump.", thermostatOpening: "108°C Electronically mapped thermostat.", oilCooler: "External air-to-oil cooler." }, fuelSystem: { systemType: "Bosch High Precision Direct Injection.", maxPressure: "200 Bar (Fuel Rail).", injectors: "6x Bosch Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "550 Nm", maxSafePowerStock: "420 hp (The open-deck block and cast connecting rods are the limiting factors).", maxSafeRPM: "7000 RPM", weakestLink: "Plastic Charge Pipe (Fatal), Rod Bearings (Fatal), OFHG (Fatal), Electric Water Pump." }, electrical: { coils: "Individual Coil Pack system (6x Coil-on-Plug).", ecu: "Bosch MEVD17.2." } },
