          oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "CRITICAL: Use high-quality 5W-30 Synthetic. Frequent changes are mandatory to protect the fragile rod bearings and turbocharger.", parts: ["6.5L 5W-30", "Mann Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "80 EUR" }, { interval: "20,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace the panel paper filter element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "60,000 km", timeLimit: "6 years", task: "Fuel Filter", details: "Replace the inline fuel filter.", parts: ["Fuel Filter"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "40 EUR" } ],
