          oilAndFilters: [ { interval: "7,500 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "CRITICAL: Use high-quality 5W-40 Synthetic. The immense heat of the V8 requires very frequent oil changes to protect the Valvetronic and turbos.", parts: ["8.5L 5W-40", "Mann Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "110 EUR" }, { interval: "20,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace the two panel paper filter elements.", parts: ["2x Air Filters"], importance: "High", laborDifficulty: "Easy", estimatedCost: "50 EUR" } ],
          ignitionAndEngine: [ { interval: "60,000 km", timeLimit: "Unlimited", task: "Hot-V Cooling Line Replacement", details: "Proactively replace the rubber coolant and oil feed lines for the turbos located in the hot valley before they crack and leak.", parts: ["Turbo Line Kit"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "350 EUR" }, { interval: "150,000 km", timeLimit: "Unlimited", task: "Valve Stem Seal Replacement", details: "When the engine begins smoking blue after idling, the valve stem seals must be replaced using specialized pneumatic tools to prevent catalyst destruction.", parts: ["Valve Stem Seals", "Special Tools"], importance: "High", laborDifficulty: "Expert", estimatedCost: "1800+ EUR" }, { interval: "60,000 km", timeLimit: "Unlimited", task: "Intake Valve Walnut Blasting", details: "Remove the intake manifolds and blast the intake valves with crushed walnut shells to clear the carbon sludge buildup.", parts: ["Intake Gaskets", "Labor"], importance: "High", laborDifficulty: "Expert", estimatedCost: "400 EUR" }, { interval: "As Needed", timeLimit: "Unlimited", task: "Valvetronic Motor Replacement", details: "If the engine loses power or throws Valvetronic codes, the electric actuator motors on the valve covers must be replaced.", parts: ["2x VDO Motors"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "500 EUR" }, { interval: "30,000 km", timeLimit: "3 years", task: "Spark Plugs", details: "Replace spark plugs. Tuned engines require 1-step colder plugs gapped tightly.", parts: ["8x NGK Plugs"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "110 EUR" } ],
