          coolingAndHvac: [ { interval: "40,000 km", timeLimit: "3 years", task: "Coolant Flush", details: "CRITICAL: Drain and refill the massive 14.0L cooling system (both circuits). Old coolant corrodes the aluminum block.", parts: ["14.0L LC-87 Coolant"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "90 EUR" }, { interval: "80,000 km", timeLimit: "8 years", task: "Water Pump & Thermostat", details: "Proactively replace the mechanical water pump and upgrade to a 90C thermostat to drastically lower the destructive engine bay temperatures.", parts: ["Water Pump", "90C Thermostat"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "350 EUR" } ],
