          ignitionAndEngine: [ { interval: "100,000 km", timeLimit: "Unlimited", task: "Timing Chain Overhaul (Engine Out)", details: "CRITICAL: A massive teardown requiring the removal of the entire engine to replace the rear-mounted timing chain and brittle plastic guides before they snap.", parts: ["Timing Kit", "Special Tools"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "1500+ EUR" }, { interval: "Immediately", timeLimit: "Unlimited", task: "Swirl Flap Delete", details: "CRITICAL: The plastic swirl flaps in the intake manifold can break and destroy the engine. Remove the manifold and install blanking plates.", parts: ["Blanking Plates"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "50 EUR" }, { interval: "150,000 km", timeLimit: "Unlimited", task: "Vibration Damper Replacement", details: "CRITICAL: Proactively replace the heavy main crankshaft pulley. The rubber core tears and will eventually destroy the serpentine belt system.", parts: ["Corteco Damper", "Bolts"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "250 EUR" }, { interval: "60,000 km", timeLimit: "Unlimited", task: "EGR Valve Cleaning", details: "Remove the EGR valve and thoroughly clean out the thick, sticky black carbon soot to prevent limp mode and rough idling.", parts: ["Brake Cleaner", "Gasket"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "20 EUR" }, { interval: "100,000 km", timeLimit: "8 years", task: "Glow Plugs & Relay", details: "Replace all 4 glow plugs and the glow plug control module. Essential for cold weather starting and triggering DPF regenerations.", parts: ["4x Plugs", "Relay"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "160 EUR" } ],
