          oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "CRITICAL: Use ONLY high quality 5W-30 Synthetic. The timing chain relies entirely on pristine oil to survive.", parts: ["7.2L 5W-30", "Mann Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "85 EUR" }, { interval: "20,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace the panel paper filter element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "30,000 km", timeLimit: "3 years", task: "Diesel Fuel Filter", details: "CRITICAL: Replace the inline metal fuel filter to protect the Bosch CP4.2 fuel pump.", parts: ["Fuel Filter"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "35 EUR" } ],
          ignitionAndEngine: [ { interval: "Immediately", timeLimit: "Unlimited", task: "Swirl Flap Delete", details: "CRITICAL: The plastic swirl flaps in the intake manifold WILL break and destroy the engine. Remove the manifold and install blanking plates.", parts: ["Blanking Plates", "Intake Gaskets"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "50 EUR" }, { interval: "150,000 km", timeLimit: "Unlimited", task: "Vibration Damper Replacement", details: "CRITICAL: Proactively replace the heavy main crankshaft pulley. The rubber core tears and will eventually destroy the serpentine belt system.", parts: ["Corteco Damper", "Bolts"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "250 EUR" }, { interval: "80,000 km", timeLimit: "8 years", task: "Thermostat Replacement", details: "Replace the main engine thermostat. They fail open, causing the engine to run cold and preventing DPF regeneration.", parts: ["Main T-Stat"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "70 EUR" }, { interval: "100,000 km", timeLimit: "8 years", task: "Glow Plugs & Relay", details: "Replace all 6 glow plugs and the control module. Essential for cold weather starting and DPF regenerations.", parts: ["6x Plugs", "Relay"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "180 EUR" }, { interval: "250,000 km", timeLimit: "Unlimited", task: "Timing Chain Overhaul (Engine Out)", details: "A massive teardown requiring the removal of the entire engine to replace the rear-mounted timing chain and guides once they eventually stretch.", parts: ["Timing Kit", "Special Tools"], importance: "High", laborDifficulty: "Expert", estimatedCost: "1500+ EUR" } ],
