        engineeringData: { blockDesign: "Closed-deck Aluminum block with wire-arc sprayed cylinder liners. The B46 is identical to the B48 architecture, but specifically engineered to meet strict Super Ultra Low Emissions Vehicle (SULEV) standards in certain US states (like California). The closed-deck design provides immense rigidity and durability.", crankshaft: "Forged Steel, supported by 5 main bearings. Features integrated balance shafts for exceptional smoothness.", pistonSpeed: "15.0 m/s @ 6000 RPM.", alternator: "180A Valeo (Multi-rib belt driven).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy. Features the lower 10.2:1 compression ratio specifically designed to safely handle higher boost pressures from the factory, making it incredibly robust for aftermarket tuning.", wristPinDiameter: "22 mm.", connectingRodLength: "148 mm.", rodBoltSize: "M9.", crankMainJournal: "50.0 mm.", crankRodJournal: "50.0 mm.", rodRatio: "1.56." }, cylinderHead: { combustionChamberVol: "Pent-roof combustion chamber optimized for direct injection.", intakePortFlow: "16-valve DOHC design.", valveSizes: "Intake: 32.0 mm / Exhaust: 29.0 mm.", valveStemDiameter: "5.0 mm.", camshaftDuration: "Variable on BOTH Intake and Exhaust sides. Controlled dynamically by Double VANOS and Valvetronic.", lifterType: "Hydraulic bucket tappets.", specialFeature: "SULEV Hardware. The B46 utilizes a massive, highly restrictive catalytic converter combined with an Environmental Air Catalyst (EAC) sensor to drastically reduce emissions. This hardware makes repairs significantly more expensive than the standard B48." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Variable displacement map-controlled pump.", thermostatOpening: "108°C Electronically mapped heat management module.", oilCooler: "Features an external air-to-oil cooler." }, fuelSystem: { systemType: "Bosch High Precision Direct Injection.", maxPressure: "350 Bar (Fuel Rail).", injectors: "4x Bosch Solenoid Injectors (SULEV specific)." }, tuningLimits: { maxSafeTorqueStock: "500 Nm", maxSafePowerStock: "400 hp (The block is strong, but the SULEV catalytic converter represents a massive thermal and physical restriction).", maxSafeRPM: "6800 RPM", weakestLink: "SULEV Catalytic Converter, EAC Sensor, Plastic Oil Filter Housing, Plastic Thermostat Housing, Charge Pipe." }, electrical: { coils: "Individual Coil Pack system (4x Coil-on-Plug).", ecu: "Bosch MG1 (Heavily encrypted)." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent the failure of the highly reliable but complex B46 engine.", parts: [ { category: "Aluminum Oil Filter Housing", brand: "Aftermarket Billet", note: "CRITICAL: Replaces the crack-prone factory plastic housing." }, { category: "Thermostat Housing / Heat Management", brand: "Genuine BMW / INA", note: "CRITICAL: Replaces the weeping plastic factory unit." }, { category: "Aluminum Charge Pipe", brand: "FTP / VRSF", note: "CRITICAL: Replaces the exploding plastic factory pipe." }, { category: "Water Pump", brand: "Pierburg / Saleri", note: "Replace proactively to ensure bulletproof cooling." }, { category: "Valve Cover Assembly", brand: "Genuine BMW", note: "The plastic PCV valve is integrated into the cover. Cures vacuum leaks." }, { category: "Spark Plugs", brand: "NGK SILZKGR8B8S", note: "Specific plugs; MUST be replaced every 40k km." }, { category: "Vibration Damper", brand: "Corteco", note: "Replaces the tearing rubber crank pulley." }, { category: "EAC Sensor", brand: "Genuine BMW", note: "Common failure point on SULEV models. Highly expensive." } ] },
