  engineeringData: { blockDesign: "Closed-deck Aluminum block with wire-arc sprayed cylinder liners. The B58TU2 represents a highly refined evolution of BMW's 6-cylinder architecture. In the 550e, the internal combustion engine is a marvel, supplemented massively by the integrated electric motor.", crankshaft: "Forged Steel, supported by 7 main bearings. Features exceptional natural smoothness due to the inline-6 layout.", pistonSpeed: "15.0 m/s @ 6000 RPM.", alternator: "N/A (Replaced by the High-Voltage system and DC/DC converter).", rotatingAssembly: { pistonConstruction: "Forged aluminum alloy. Features an 11.0:1 compression ratio optimized for fuel efficiency and off-idle response.", wristPinDiameter: "22 mm.", connectingRodLength: "148 mm.", rodBoltSize: "M9.", crankMainJournal: "50.0 mm.", crankRodJournal: "50.0 mm.", rodRatio: "1.56." }, cylinderHead: { combustionChamberVol: "Pent-roof combustion chamber optimized for direct injection.", intakePortFlow: "24-valve DOHC design. The exhaust manifold is cast directly into the cylinder head to improve thermal efficiency.", valveSizes: "Intake: 32.0 mm / Exhaust: 29.0 mm.", valveStemDiameter: "5.0 mm.", camshaftDuration: "Variable on BOTH Intake and Exhaust sides. Controlled dynamically by Double VANOS and Valvetronic.", lifterType: "Hydraulic bucket tappets.", specialFeature: "PHEV Architecture & Dual Injection. The TU2 update adds Port Injection to completely eliminate carbon buildup. The engine is assisted entirely by the incredibly powerful 197hp electric motor integrated into the ZF transmission, drawing power from a large lithium-ion battery pack." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Variable displacement map-controlled pump.", thermostatOpening: "108°C Electronically mapped heat management module.", oilCooler: "Features an external air-to-oil cooler." }, fuelSystem: { systemType: "Bosch Dual Injection System (High Precision Direct + Port Injection).", maxPressure: "350 Bar (Direct Injection Fuel Rail).", injectors: "6x Bosch Solenoid Direct Injectors + 6x Port Injectors." }, tuningLimits: { maxSafeTorqueStock: "800 Nm (Combined)", maxSafePowerStock: "550+ hp (Combined. The block handles boost perfectly, but combined with the massive electric motor, total output pushes the transmission clutches to their absolute limit).", maxSafeRPM: "7000 RPM", weakestLink: "Plastic Oil Filter Housing, Plastic Thermostat Housing, Charge Pipe, High-Voltage A/C Compressor (KLE)." }, electrical: { coils: "Individual Coil Pack system (6x Coil-on-Plug).", ecu: "Bosch MG1 (Heavily encrypted - Requires FEMTO unlock)." } },
  recommendedParts: { description: "Crucial maintenance parts to prevent the failure of the highly complex B58 PHEV drivetrain.", parts: [ { category: "Aluminum Oil Filter Housing", brand: "Aftermarket Billet", note: "CRITICAL: Replaces the crack-prone factory plastic housing." }, { category: "Thermostat Housing / Heat Management", brand: "Genuine BMW / INA", note: "CRITICAL: Replaces the weeping plastic factory unit." }, { category: "Aluminum Charge Pipe", brand: "FTP / VRSF", note: "CRITICAL: Replaces the exploding plastic factory pipe." }, { category: "Water Pump", brand: "Pierburg / Saleri", note: "Replace proactively to ensure bulletproof cooling." }, { category: "Valve Cover Assembly", brand: "Genuine BMW", note: "The plastic PCV valve is integrated into the cover. Cures vacuum leaks." }, { category: "Spark Plugs (1-Step Colder)", brand: "NGK SILZKGR8B8S", note: "Specific plugs; MUST be replaced every 40k km. PHEVs eat spark plugs rapidly." }, { category: "Vibration Damper", brand: "Corteco", note: "Replaces the tearing rubber crank pulley." }, { category: "12V AGM Auxiliary Battery", brand: "Genuine BMW / VARTA", note: "CRITICAL: A weak 12V battery will completely disable the high-voltage system." } ] },
