      { interval: "40,000 km", timeLimit: "3 years", task: "Primary Coolant Flush", details: "Drain and refill the main engine cooling system to prevent internal block corrosion and protect the water pump.", parts: ["8.5L LC-87 Coolant"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "70 EUR" },
      { interval: "40,000 km", timeLimit: "3 years", task: "Charge-Air Coolant Flush", details: "Drain and refill the dedicated low-temperature cooling circuit for the charge-air intercooler to maintain optimal intake temps.", parts: ["3.2L LC-87 Coolant"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "50 EUR" }
