      { interval: "100,000 km", timeLimit: "8 years", task: "Serpentine Belt & Tensioner Replacement", details: "Replace the main accessory drive belt and inspect the tensioner pulleys for wear to prevent sudden loss of alternator and water pump.", parts: ["Belt Kit"], importance: "High", laborDifficulty: "Easy", estimatedCost: "90 EUR" },
      { interval: "150,000 km", timeLimit: "Unlimited", task: "Engine Mount Replacement", details: "Inspect and replace the complex vacuum-actuated fluid engine mounts if they are leaking or causing excessive cabin vibration.", parts: ["2x Lemförder Mounts"], importance: "Medium", laborDifficulty: "Advanced", estimatedCost: "280 EUR" },
      { interval: "100,000 km", timeLimit: "10 years", task: "Sway Bar End Links Replacement", details: "Replace worn end links if suspension clunking is heard over bumps.", parts: ["2x Lemförder Links"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "60 EUR" }
